                byte[] b = new byte[16];
                Buffer.BlockCopy(h, 0, b, 0, 16);
                return b;
            }
        }

        public static Keys Derive(string password, byte[] salt)
        {
            using (Rfc2898DeriveBytes r = new Rfc2898DeriveBytes(password, salt, 20000))
            {
                byte[] all = r.GetBytes(64);
                Keys k = new Keys();
                Buffer.BlockCopy(all, 0, k.Enc, 0, 32);
                Buffer.BlockCopy(all, 32, k.Mac, 0, 32);
                return k;
            }
        }
    }

    public static class Sym
    {
        public static byte[] Encrypt(byte[] key, byte[] iv, byte[] data)
        {
            using (RijndaelManaged a = New(key, iv))
            using (MemoryStream ms = new MemoryStream())
            using (CryptoStream cs = new CryptoStream(ms, a, CryptoStreamMode.Write))
            {
                cs.Write(data, 0, data.Length);
                cs.FlushFinalBlock();
                return ms.ToArray();
            }
        }

        public static byte[] Decrypt(byte[] key, byte[] iv, byte[] data)
        {
            using (RijndaelManaged a = New(key, iv))
            using (MemoryStream ms = new MemoryStream(data))
            using (CryptoStream cs = new CryptoStream(ms, a, CryptoStreamMode.Decrypt))
            using (MemoryStream outMs = new MemoryStream())
            {
                byte[] buf = new byte[8192];
                int n;
                while ((n = cs.Read(buf, 0, buf.Length)) > 0) outMs.Write(buf, 0, n);
                return outMs.ToArray();
            }
        }

        private static RijndaelManaged New(byte[] key, byte[] iv)
        {
            RijndaelManaged a = new RijndaelManaged();
            a.KeySize = 256;
            a.BlockSize = 128;
