#include <openssl/err.h>
#include <openssl/core_names.h>

#include <cstdio>
#include <memory>

namespace locker {

std::string hex(const uint8_t* data, size_t len) {
  static const char* d = "0123456789abcdef";
  std::string s(len * 2, '0');
  for (size_t i = 0; i < len; ++i) { s[i*2] = d[data[i] >> 4]; s[i*2+1] = d[data[i] & 0xF]; }
  return s;
}

std::string opensslError() {
  unsigned long e = ERR_get_error();
  if (!e) return "no-openssl-error";
  char buf[256];
  ERR_error_string_n(e, buf, sizeof(buf));
  return std::string(buf);
}

Bytes randomBytes(size_t n) {
  Bytes b(n);
  if (n && RAND_bytes(b.data(), static_cast<int>(n)) != 1) { b.clear(); return b; }
  return b;
}

Bytes sha256(const uint8_t* data, size_t len) {
  Bytes out(SHA256_DIGEST_LENGTH);
  unsigned int outLen = 0;
  EVP_MD_CTX* ctx = EVP_MD_CTX_new();
  EVP_DigestInit_ex(ctx, EVP_sha256(), nullptr);
  EVP_DigestUpdate(ctx, data, len);
  EVP_DigestFinal_ex(ctx, out.data(), &outLen);
  EVP_MD_CTX_free(ctx);
  out.resize(outLen);
  return out;
}

namespace {
struct KeyDeleter { void operator()(EVP_PKEY* k) const { EVP_PKEY_free(k); } };
using PKey = std::unique_ptr<EVP_PKEY, KeyDeleter>;

PKey readPem(const std::string& path, bool pub) {
  FILE* f = std::fopen(path.c_str(), "rb");
  if (!f) return PKey(nullptr);
  PKey k(pub ? PEM_read_PUBKEY(f, nullptr, nullptr, nullptr)
             : PEM_read_PrivateKey(f, nullptr, nullptr, nullptr));
  std::fclose(f);
  return k;
}
} // namespace

bool loadPublicKey(const std::string& pemPath, Bytes& modulusOut, int& err) {
  PKey k = readPem(pemPath, true);
  if (!k) { err = 1; return false; }
  BIGNUM* n = nullptr;
  if (EVP_PKEY_get_bn_param(k.get(), OSSL_PKEY_PARAM_RSA_N, &n) != 1 || !n) { err = 2; return false; }
  modulusOut.assign(BN_num_bytes(n), 0);
  BN_bn2bin(n, modulusOut.data());
  BN_free(n);
  if (modulusOut.size() < 256) { err = 3; return false; }   // < RSA-2048
  return true;
}

bool loadPrivateKey(const std::string& pemPath, Bytes& privOut, int& err) {
  PKey k = readPem(pemPath, false);
  if (!k) { err = 1; return false; }
  size_t len = 0;
  if (i2d_PrivateKey(k.get(), nullptr) == 0) { err = 4; return false; }
  privOut.resize(len);
  unsigned char* p = privOut.data();
  if (i2d_PrivateKey(k.get(), &p) == 0) { err = 5; return false; }
  return true;
}

bool rsaOaepWrap(const Bytes& pemKey, const uint8_t* key, size_t keyLen, Bytes& out, int& err) {
  PKey k = readPemFromBytes(pemKey, true, err);
  if (!k) return false;
  EVP_PKEY_CTX* ctx = EVP_PKEY_CTX_new(k.get(), nullptr);
  if (!ctx) { err = 6; return false; }
  bool ok = EVP_PKEY_encrypt_init(ctx) == 1
         && EVP_PKEY_CTX_set_rsa_padding(ctx, RSA_PKCS1_OAEP_PADDING) == 1
         && EVP_PKEY_CTX_set_rsa_oaep_md(ctx, EVP_sha256()) == 1
         && EVP_PKEY_CTX_set_rsa_mgf1_md(ctx, EVP_sha256()) == 1;
  size_t outLen = 0;
  ok = ok && EVP_PKEY_encrypt(ctx, nullptr, &outLen, key, keyLen) == 1;
  if (ok) {
    out.assign(outLen, 0);
    ok = EVP_PKEY_encrypt(ctx, out.data(), &outLen, key, keyLen) == 1;
